package com.npcattackercount;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class NpcAttackerCountPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(NpcAttackerCountPlugin.class);
		RuneLite.main(args);
	}
}

package com.npcattackercount;

import com.npcattackercount.AttackerCounter.Filter;
import com.npcattackercount.AttackerCounter.Tally;
import com.npcattackercount.AttackerCounter.Targeting;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AttackerCounterTest
{
	/** Stands in for an NPC. No equals override, so two Mobs are equal only if they are the same Mob. */
	private static final class Mob
	{
		final String name;

		Mob(String name)
		{
			this.name = name;
		}
	}

	private static final Filter ALL = Filter.of(true, 1, "");

	private final List<Targeting<Mob>> obs = new ArrayList<>();

	private void other(Mob m)
	{
		obs.add(new Targeting<>(m, m.name, false, false));
	}

	private void groupMate(Mob m)
	{
		obs.add(new Targeting<>(m, m.name, false, true));
	}

	private void me(Mob m)
	{
		obs.add(new Targeting<>(m, m.name, true, false));
	}

	@Test
	public void nobodyTargetingGivesEmptyMap()
	{
		assertTrue(AttackerCounter.count(obs, ALL).isEmpty());
	}

	@Test
	public void countsPlayersPerTarget()
	{
		Mob cow = new Mob("Cow");
		Mob goblin = new Mob("Goblin");
		other(cow);
		other(cow);
		other(cow);
		other(goblin);

		Map<Mob, Tally> r = AttackerCounter.count(obs, ALL);
		assertEquals(3, r.get(cow).getTotal());
		assertEquals(1, r.get(goblin).getTotal());
	}

	@Test
	public void sameNameDifferentNpcsAreCountedSeparately()
	{
		Mob crabA = new Mob("Gemstone Crab");
		Mob crabB = new Mob("Gemstone Crab");
		other(crabA);
		other(crabA);
		other(crabB);

		Map<Mob, Tally> r = AttackerCounter.count(obs, ALL);
		assertEquals(2, r.size());
		assertEquals(2, r.get(crabA).getTotal());
		assertEquals(1, r.get(crabB).getTotal());
	}

	@Test
	public void selfIsCountedWhenIncluded()
	{
		Mob cow = new Mob("Cow");
		me(cow);
		other(cow);

		assertEquals(2, AttackerCounter.count(obs, Filter.of(true, 1, "")).get(cow).getTotal());
	}

	@Test
	public void selfIsSkippedWhenExcluded()
	{
		Mob cow = new Mob("Cow");
		me(cow);
		other(cow);

		assertEquals(1, AttackerCounter.count(obs, Filter.of(false, 1, "")).get(cow).getTotal());
	}

	@Test
	public void targetOnlyIHaveDisappearsWhenSelfExcluded()
	{
		Mob cow = new Mob("Cow");
		me(cow);

		assertTrue(AttackerCounter.count(obs, Filter.of(false, 1, "")).isEmpty());
	}

	@Test
	public void outsidersAreEveryoneExceptMeAndMyGroup()
	{
		Mob crab = new Mob("Gemstone Crab");
		me(crab);
		groupMate(crab);
		groupMate(crab);
		other(crab);

		Tally t = AttackerCounter.count(obs, ALL).get(crab);
		assertEquals(4, t.getTotal());
		assertEquals(1, t.getOutsiders());
	}

	@Test
	public void noOutsidersWhenOnlyGroupIsOnIt()
	{
		Mob crab = new Mob("Gemstone Crab");
		me(crab);
		groupMate(crab);

		assertEquals(0, AttackerCounter.count(obs, ALL).get(crab).getOutsiders());
	}

	@Test
	public void minimumCountDropsQuietTargets()
	{
		Mob busy = new Mob("Cow");
		Mob quiet = new Mob("Goblin");
		other(busy);
		other(busy);
		other(quiet);

		Map<Mob, Tally> r = AttackerCounter.count(obs, Filter.of(true, 2, ""));
		assertEquals(2, r.get(busy).getTotal());
		assertNull(r.get(quiet));
	}

	@Test
	public void nameFilterIsCaseInsensitiveAndTakesWildcards()
	{
		Mob crab = new Mob("Gemstone Crab");
		Mob cow = new Mob("Cow");
		Mob goblin = new Mob("Goblin");
		other(crab);
		other(cow);
		other(goblin);

		Map<Mob, Tally> r = AttackerCounter.count(obs, Filter.of(true, 1, " GEMSTONE*, cow "));
		assertEquals(1, r.get(crab).getTotal());
		assertEquals(1, r.get(cow).getTotal());
		assertNull(r.get(goblin));
	}

	@Test
	public void unnamedNpcOnlyPassesAnEmptyFilter()
	{
		Mob nameless = new Mob(null);
		other(nameless);

		assertEquals(1, AttackerCounter.count(obs, ALL).get(nameless).getTotal());
		obs.clear();
		other(nameless);
		assertTrue(AttackerCounter.count(obs, Filter.of(true, 1, "cow")).isEmpty());
	}

	@Test
	public void nullTargetIsIgnored()
	{
		obs.add(new Targeting<>(null, null, false, false));
		assertTrue(AttackerCounter.count(obs, ALL).isEmpty());
	}

	@Test
	public void blankEntriesInNameListAreDropped()
	{
		assertTrue(AttackerCounter.parseNames(" , ,, ").isEmpty());
		assertTrue(AttackerCounter.parseNames(null).isEmpty());
		assertEquals(2, AttackerCounter.parseNames("a,,b").size());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void resultCannotBeModified()
	{
		Mob cow = new Mob("Cow");
		other(cow);
		AttackerCounter.count(obs, ALL).clear();
	}

	@Test
	public void onlyMineKeepsJustMyTarget()
	{
		Mob mine = new Mob("Cow");
		Mob theirs = new Mob("Cow");
		me(mine);
		other(mine);
		other(theirs);
		other(theirs);

		Map<Mob, Tally> r = AttackerCounter.count(obs, Filter.of(true, true, 1, ""));
		assertEquals(1, r.size());
		assertEquals(2, r.get(mine).getTotal());
	}

	@Test
	public void onlyMineStillFindsMyTargetWhenIAmNotCounted()
	{
		Mob mine = new Mob("Cow");
		me(mine);
		other(mine);
		other(mine);

		Map<Mob, Tally> r = AttackerCounter.count(obs, Filter.of(false, true, 1, ""));
		assertEquals(2, r.get(mine).getTotal());
	}

	@Test
	public void onlyMineWithNoTargetShowsNothing()
	{
		other(new Mob("Cow"));
		assertTrue(AttackerCounter.count(obs, Filter.of(true, true, 1, "")).isEmpty());
	}

	@Test
	public void emptyPatternListMatchesEverything()
	{
		assertTrue(AttackerCounter.nameMatches("Anything", new ArrayList<>()));
		assertFalse(AttackerCounter.nameMatches("Cow", AttackerCounter.parseNames("goblin")));
	}
}

package com.npcattackercount;

import static org.junit.Assert.assertArrayEquals;
import org.junit.Test;

public class FacingTest
{
	@Test
	public void cardinalOrientations()
	{
		assertArrayEquals(new int[]{0, -1}, Facing.step(0));
		assertArrayEquals(new int[]{-1, 0}, Facing.step(512));
		assertArrayEquals(new int[]{0, 1}, Facing.step(1024));
		assertArrayEquals(new int[]{1, 0}, Facing.step(1536));
	}

	@Test
	public void nearlyCardinalRoundsToNearest()
	{
		assertArrayEquals(new int[]{0, 1}, Facing.step(1024 + 200));
		assertArrayEquals(new int[]{0, -1}, Facing.step(2047));
	}
}

package com.npcattackercount;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(NpcAttackerCountConfig.GROUP)
public interface NpcAttackerCountConfig extends Config
{
	// Permanent once published: every user's saved settings are stored under
	// this name, and changing it silently resets them.
	String GROUP = "npc-attacker-count";

	@ConfigSection(
		name = "Counting",
		description = "Who and what is counted",
		position = 0
	)
	String counting = "counting";

	@ConfigSection(
		name = "Display",
		description = "How and where the number is drawn",
		position = 1
	)
	String display = "display";

	@ConfigSection(
		name = "Outsiders",
		description = "Change the colour when someone outside your group is on the NPC",
		position = 2
	)
	String outsiders = "outsiders";

	// ---- Counting ----

	@ConfigItem(
		keyName = "includeSelf",
		name = "Include yourself",
		description = "Count your own character toward the number",
		section = counting,
		position = 0
	)
	default boolean includeSelf()
	{
		return true;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(
		keyName = "minimumCount",
		name = "Minimum to show",
		description = "Only show the number when at least this many players are on the NPC",
		section = counting,
		position = 1
	)
	default int minimumCount()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "npcNames",
		name = "Only these names",
		description = "Comma-separated NPC or object names, * as wildcard, e.g. Gemstone Crab, *dragon, Yew tree. Empty counts everything",
		section = counting,
		position = 2
	)
	default String npcNames()
	{
		return "";
	}

	@ConfigItem(
		keyName = "onlyMyTarget",
		name = "Only my target",
		description = "Show the number only on the NPC or object you are on yourself",
		section = counting,
		position = 3
	)
	default boolean onlyMyTarget()
	{
		return false;
	}

	@ConfigItem(
		keyName = "countObjects",
		name = "Count at objects",
		description = "Also count players using objects - trees, rocks, stalls. Inferred from who is animating while facing the object, so less exact than NPCs",
		section = counting,
		position = 4
	)
	default boolean countObjects()
	{
		return false;
	}

	// ---- Display ----

	@ConfigItem(
		keyName = "alwaysShow",
		name = "Show without health bar",
		description = "Show the number even when the NPC's health bar is not visible",
		section = display,
		position = 0
	)
	default boolean alwaysShow()
	{
		return false;
	}

	@ConfigItem(
		keyName = "colour",
		name = "Colour",
		description = "Colour of the number",
		section = display,
		position = 1
	)
	default Color colour()
	{
		return Color.YELLOW;
	}

	@ConfigItem(
		keyName = "position",
		name = "Position",
		description = "Where the number sits relative to the health bar",
		section = display,
		position = 2
	)
	default NumberPosition position()
	{
		return NumberPosition.RIGHT_OF_BAR;
	}

	@Range(min = -100, max = 100)
	@ConfigItem(
		keyName = "nudgeRight",
		name = "Nudge right",
		description = "Move the number right (+) or left (-), in pixels",
		section = display,
		position = 3
	)
	default int nudgeRight()
	{
		return 0;
	}

	@Range(min = -100, max = 100)
	@ConfigItem(
		keyName = "nudgeDown",
		name = "Nudge down",
		description = "Move the number down (+) or up (-), in pixels",
		section = display,
		position = 4
	)
	default int nudgeDown()
	{
		return 0;
	}

	// ---- Outsiders ----

	@ConfigItem(
		keyName = "highlightOutsiders",
		name = "Highlight outsiders",
		description = "Use the outsider colour when anyone not in your group is on the NPC",
		section = outsiders,
		position = 0
	)
	default boolean highlightOutsiders()
	{
		return false;
	}

	@ConfigItem(
		keyName = "splitOutsiders",
		name = "Split group / outsiders",
		description = "Show two numbers side by side: your group in the main colour, outsiders in the outsider colour",
		section = outsiders,
		position = 1
	)
	default boolean splitOutsiders()
	{
		return false;
	}

	@ConfigItem(
		keyName = "outsiderColour",
		name = "Outsider colour",
		description = "Colour for outsiders - the whole number when highlighting, or the second number when split",
		section = outsiders,
		position = 2
	)
	default Color outsiderColour()
	{
		return Color.RED;
	}

	@ConfigItem(
		keyName = "groupIronman",
		name = "Group: ironman group",
		description = "Your Group Ironman members count as your group",
		section = outsiders,
		position = 3
	)
	default boolean groupIronman()
	{
		return true;
	}

	@ConfigItem(
		keyName = "groupFriends",
		name = "Group: friends list",
		description = "Players on your friends list count as your group",
		section = outsiders,
		position = 4
	)
	default boolean groupFriends()
	{
		return false;
	}

	@ConfigItem(
		keyName = "groupFriendsChat",
		name = "Group: friends chat",
		description = "Members of your current friends chat count as your group",
		section = outsiders,
		position = 5
	)
	default boolean groupFriendsChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "groupClan",
		name = "Group: clan",
		description = "Members of your clan count as your group",
		section = outsiders,
		position = 6
	)
	default boolean groupClan()
	{
		return false;
	}
}

package com.npcattackercount;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;
import net.runelite.client.util.WildcardMatcher;

/**
 * Turns one tick's worth of "player X is targeting Y" into a count per target.
 *
 * Deliberately knows nothing about the game client. The plugin resolves every
 * client-dependent fact (is this player me, is this player in my group, what is
 * the target called) into plain values first, so this class can be tested with
 * strings standing in for NPCs.
 *
 * @param <T> the target type. {@code NPC} in the plugin, anything in tests.
 */
final class AttackerCounter
{
	private AttackerCounter()
	{
	}

	/** One player's current target, with the facts about that player already decided. */
	@Value
	static class Targeting<T>
	{
		T target;
		String targetName;
		boolean self;
		boolean groupMember;
	}

	/** What the overlay draws for one target. */
	@Value
	static class Tally
	{
		int total;
		/** Players counted in {@link #total} who are neither you nor in your group. */
		int outsiders;
	}

	@Value
	static class Filter
	{
		boolean includeSelf;
		/** Keep only the target you are on yourself. Works whether or not you are counted. */
		boolean onlyMine;
		int minimumCount;
		/** Lower-case wildcard patterns. Empty means every target is counted. */
		List<String> namePatterns;

		static Filter of(boolean includeSelf, int minimumCount, String nameList)
		{
			return of(includeSelf, false, minimumCount, nameList);
		}

		static Filter of(boolean includeSelf, boolean onlyMine, int minimumCount, String nameList)
		{
			return new Filter(includeSelf, onlyMine, minimumCount, parseNames(nameList));
		}
	}

	/**
	 * Targets are keyed by identity, not equality: two Gemstone Crabs are two
	 * entries even though everything about them compares equal. The client keeps
	 * one object per loaded NPC, so identity is exactly "this particular NPC".
	 *
	 * Returns an unmodifiable map, so a reader on another thread can never see
	 * it half-built.
	 */
	static <T> Map<T, Tally> count(Iterable<Targeting<T>> observations, Filter filter)
	{
		Map<T, int[]> running = new IdentityHashMap<>();
		for (Targeting<T> o : observations)
		{
			if (o.getTarget() == null
				|| !nameMatches(o.getTargetName(), filter.getNamePatterns()))
			{
				continue;
			}

			// [0] = total, [1] = outsiders, [2] = 1 if I'm on it. A mutable
			// triple avoids allocating a new Tally on every increment.
			int[] c = running.computeIfAbsent(o.getTarget(), k -> new int[3]);
			if (o.isSelf())
			{
				// Recorded before the includeSelf check: "only my target" must
				// still find my target when I'm not counted toward it.
				c[2] = 1;
				if (!filter.isIncludeSelf())
				{
					continue;
				}
			}
			c[0]++;
			if (!o.isSelf() && !o.isGroupMember())
			{
				c[1]++;
			}
		}

		Map<T, Tally> result = new IdentityHashMap<>();
		for (Map.Entry<T, int[]> e : running.entrySet())
		{
			int[] c = e.getValue();
			if (filter.isOnlyMine() && c[2] == 0)
			{
				continue;
			}
			if (c[0] >= filter.getMinimumCount())
			{
				result.put(e.getKey(), new Tally(c[0], c[1]));
			}
		}
		return Collections.unmodifiableMap(result);
	}

	static boolean nameMatches(String name, List<String> patterns)
	{
		if (patterns.isEmpty())
		{
			return true;
		}
		if (name == null)
		{
			return false;
		}
		for (String p : patterns)
		{
			if (WildcardMatcher.matches(p, name))
			{
				return true;
			}
		}
		return false;
	}

	static List<String> parseNames(String nameList)
	{
		List<String> out = new ArrayList<>();
		if (nameList == null)
		{
			return out;
		}
		for (String part : nameList.split(","))
		{
			String p = part.trim().toLowerCase();
			if (!p.isEmpty())
			{
				out.add(p);
			}
		}
		return Collections.unmodifiableList(out);
	}
}

package com.npcattackercount;

import com.npcattackercount.AttackerCounter.Tally;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.Value;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.api.Renderable;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws the last tick's counts. Runs every frame, so it only looks things up
 * and draws - all counting happened once, on the tick.
 */
class NpcAttackerCountOverlay extends Overlay
{
	/**
	 * World height above the model top that projects onto the health bar's
	 * vertical centre. Measured in game: at +15 the bar's centre line and the
	 * projected point coincide to within a pixel or two.
	 */
	private static final int BAR_ANCHOR_HEIGHT = 15;
	/** Width of an ordinary NPC's bar, used when the game reports no scale. */
	private static final int DEFAULT_BAR_WIDTH = 30;
	/** Half the bar's height in pixels. */
	private static final int HALF_BAR_HEIGHT = 3;
	/** Pixels between the bar and the number. */
	private static final int GAP = 4;
	/** Pixels between the group and outsider numbers in split mode. */
	private static final int SPLIT_GAP = 4;
	/** World height used when an object reports no model height. */
	private static final int DEFAULT_OBJECT_HEIGHT = 100;
	/** World units between the top of an object's model and its number. */
	private static final int OBJECT_CLEARANCE = 20;

	private final NpcAttackerCountPlugin plugin;
	private final NpcAttackerCountConfig config;

	@Value
	private static class Segment
	{
		String text;
		Color colour;
	}

	@Inject
	NpcAttackerCountOverlay(NpcAttackerCountPlugin plugin, NpcAttackerCountConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		FontMetrics fm = graphics.getFontMetrics();
		for (Map.Entry<NPC, Tally> e : plugin.getSnapshot().entrySet())
		{
			NPC npc = e.getKey();

			// -1 means the game isn't drawing a health bar for this NPC.
			if (!config.alwaysShow() && npc.getHealthRatio() < 0)
			{
				continue;
			}

			List<Segment> segments = segments(e.getValue());
			int width = width(segments, fm);

			// Only the projected point matters here; the text passed is irrelevant
			// because the x is re-centred below.
			Point anchor = npc.getCanvasTextLocation(graphics, "", npc.getLogicalHeight() + BAR_ANCHOR_HEIGHT);
			if (anchor == null)
			{
				continue; // off screen
			}

			Point at = place(anchor, width, fm.getAscent(), npc.getHealthScale());
			draw(graphics, fm, segments, at.getX(), at.getY());
		}

		for (Map.Entry<TileObject, Tally> e : plugin.getObjectSnapshot().entrySet())
		{
			TileObject object = e.getKey();
			List<Segment> segments = segments(e.getValue());
			int width = width(segments, fm);

			// Objects have no health bar, so the number sits centred above the model.
			Point anchor = object.getCanvasTextLocation(graphics, "", modelHeight(object) + OBJECT_CLEARANCE);
			if (anchor == null)
			{
				continue;
			}
			draw(graphics, fm, segments, anchor.getX() - width / 2 + config.nudgeRight(), anchor.getY() + config.nudgeDown());
		}
		return null;
	}

	private static int modelHeight(TileObject object)
	{
		Renderable model = object instanceof GameObject ? ((GameObject) object).getRenderable()
			: object instanceof WallObject ? ((WallObject) object).getRenderable1()
			: null;
		return model != null && model.getModelHeight() > 0 ? model.getModelHeight() : DEFAULT_OBJECT_HEIGHT;
	}

	private static int width(List<Segment> segments, FontMetrics fm)
	{
		int width = SPLIT_GAP * (segments.size() - 1);
		for (Segment s : segments)
		{
			width += fm.stringWidth(s.getText());
		}
		return width;
	}

	private static void draw(Graphics2D graphics, FontMetrics fm, List<Segment> segments, int x, int baseline)
	{
		for (Segment s : segments)
		{
			OverlayUtil.renderTextLocation(graphics, new Point(x, baseline), s.getText(), s.getColour());
			x += fm.stringWidth(s.getText()) + SPLIT_GAP;
		}
	}

	/**
	 * Split mode draws two numbers - your group (you included, if counted) and
	 * outsiders - each in its own colour. A zero side is left out; the colour
	 * says which one remains.
	 */
	private List<Segment> segments(Tally tally)
	{
		List<Segment> out = new ArrayList<>(2);
		if (config.splitOutsiders())
		{
			int group = tally.getTotal() - tally.getOutsiders();
			if (group > 0)
			{
				out.add(new Segment(Integer.toString(group), config.colour()));
			}
			if (tally.getOutsiders() > 0)
			{
				out.add(new Segment(Integer.toString(tally.getOutsiders()), config.outsiderColour()));
			}
			return out;
		}

		Color colour = config.highlightOutsiders() && tally.getOutsiders() > 0
			? config.outsiderColour()
			: config.colour();
		out.add(new Segment(Integer.toString(tally.getTotal()), colour));
		return out;
	}

	/**
	 * The health bar is a fixed-size sprite centred on a projected point, so once
	 * that point is known everything else is in screen pixels and holds at any
	 * camera zoom.
	 *
	 * @param bar the bar's centre (x and y)
	 * @param textWidth total width of everything drawn
	 * @param ascent font ascent; digits have no descenders, so this is their height
	 * @param barWidth the NPC's health scale, which is the bar's width in pixels
	 * @return where to draw: left edge x, baseline y
	 */
	private Point place(Point bar, int textWidth, int ascent, int barWidth)
	{
		int halfBar = (barWidth > 0 ? barWidth : DEFAULT_BAR_WIDTH) / 2;
		int levelBaseline = bar.getY() + ascent / 2;
		int x;
		int y;
		switch (config.position())
		{
			case LEFT_OF_BAR:
				x = bar.getX() - halfBar - GAP - textWidth;
				y = levelBaseline;
				break;
			case ABOVE_BAR:
				x = bar.getX() - textWidth / 2;
				y = bar.getY() - HALF_BAR_HEIGHT - GAP;
				break;
			case BELOW_BAR:
				x = bar.getX() - textWidth / 2;
				y = bar.getY() + HALF_BAR_HEIGHT + GAP + ascent;
				break;
			case RIGHT_OF_BAR:
			default:
				x = bar.getX() + halfBar + GAP;
				y = levelBaseline;
				break;
		}
		return new Point(x + config.nudgeRight(), y + config.nudgeDown());
	}
}

package com.npcattackercount;

import com.google.inject.Provides;
import com.npcattackercount.AttackerCounter.Filter;
import com.npcattackercount.AttackerCounter.Tally;
import com.npcattackercount.AttackerCounter.Targeting;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanID;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "NPC Attacker Count",
	description = "Shows how many players are targeting an NPC, next to its health bar",
	tags = {"npc", "attacker", "count", "players", "contested", "health", "bar"}
)
public class NpcAttackerCountPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private NpcAttackerCountConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NpcAttackerCountOverlay overlay;

	/**
	 * The last tick's result. Replaced whole every tick, never edited in place,
	 * so the overlay always reads one complete tick.
	 */
	@Getter
	private volatile Map<NPC, Tally> snapshot = Collections.emptyMap();

	/** Same, for objects (trees, rocks) - kept apart because they're drawn differently. */
	@Getter
	private volatile Map<TileObject, Tally> objectSnapshot = Collections.emptyMap();

	/** Rebuilt only when settings change, so the name list isn't re-parsed every tick. */
	private volatile Filter filter;

	@Override
	protected void startUp()
	{
		// Only config and overlay registration here - both are safe off the
		// client thread. The first count happens on the next GameTick, which
		// is on the client thread by construction.
		filter = buildFilter();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		snapshot = Collections.emptyMap();
		objectSnapshot = Collections.emptyMap();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (NpcAttackerCountConfig.GROUP.equals(event.getGroup()))
		{
			filter = buildFilter();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Hopping or loading a region discards every NPC; don't draw over ghosts.
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			snapshot = Collections.emptyMap();
			objectSnapshot = Collections.emptyMap();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}

		Set<String> ironmanGroup = config.groupIronman() ? ironmanGroupNames() : Collections.emptySet();
		boolean countObjects = config.countObjects();
		WorldView world = client.getTopLevelWorldView();

		List<Targeting<NPC>> npcObservations = new ArrayList<>();
		List<Targeting<TileObject>> objectObservations = new ArrayList<>();
		for (Player p : world.players())
		{
			Actor target = p.getInteracting();
			if (target instanceof NPC)
			{
				NPC npc = (NPC) target;
				npcObservations.add(new Targeting<>(npc, npc.getName(), p == me, isGroupMember(p, ironmanGroup)));
			}
			else if (target == null && countObjects)
			{
				TileObject object = facedObject(p, world);
				if (object != null)
				{
					objectObservations.add(new Targeting<>(object, objectName(object), p == me, isGroupMember(p, ironmanGroup)));
				}
			}
		}

		snapshot = AttackerCounter.count(npcObservations, filter);
		objectSnapshot = AttackerCounter.count(objectObservations, filter);
	}

	/**
	 * The object a player is using, inferred: they are playing an animation and
	 * the tile they face holds a named object. One or two tile lookups per
	 * animating player - never a scan of the scene.
	 */
	private TileObject facedObject(Player p, WorldView world)
	{
		// -1 is the game's "no animation" sentinel; standing, walking and
		// running are pose animations and don't show up here.
		if (p.getAnimation() == -1)
		{
			return null;
		}
		LocalPoint at = p.getLocalLocation();
		if (at == null)
		{
			return null;
		}
		int[] step = Facing.step(p.getOrientation());
		Tile[][] plane = world.getScene().getTiles()[world.getPlane()];
		Tile ahead = tile(plane, at.getSceneX() + step[0], at.getSceneY() + step[1]);
		if (ahead != null)
		{
			for (GameObject o : ahead.getGameObjects())
			{
				if (o != null && objectName(o) != null)
				{
					return o;
				}
			}
		}

		// Walls (Motherlode ore veins, for one) sit on the edge between two
		// tiles and are stored on only one of them - the one ahead or the
		// one the player stands on.
		Tile here = tile(plane, at.getSceneX(), at.getSceneY());
		for (Tile t : new Tile[]{ahead, here})
		{
			WallObject wall = t == null ? null : t.getWallObject();
			if (wall != null && objectName(wall) != null)
			{
				return wall;
			}
		}
		return null;
	}

	private static Tile tile(Tile[][] plane, int x, int y)
	{
		return x < 0 || y < 0 || x >= plane.length || y >= plane[x].length ? null : plane[x][y];
	}

	/** Resolves transforming objects (a tree that becomes a stump is one ID with varbit-driven forms). */
	private String objectName(TileObject o)
	{
		ObjectComposition def = client.getObjectDefinition(o.getId());
		if (def == null)
		{
			return null;
		}
		if (def.getImpostorIds() != null)
		{
			ObjectComposition impostor = def.getImpostor();
			if (impostor != null)
			{
				def = impostor;
			}
		}
		String name = def.getName();
		return name == null || "null".equals(name) ? null : name;
	}

	private boolean isGroupMember(Player p, Set<String> ironmanGroup)
	{
		return (config.groupIronman() && p.getName() != null && ironmanGroup.contains(Text.standardize(p.getName())))
			|| (config.groupFriends() && p.isFriend())
			|| (config.groupFriendsChat() && p.isFriendsChatMember())
			|| (config.groupClan() && p.isClanMember());
	}

	private Set<String> ironmanGroupNames()
	{
		ClanChannel channel = client.getClanChannel(ClanID.GROUP_IRONMAN);
		if (channel == null)
		{
			return Collections.emptySet();
		}
		Set<String> names = new HashSet<>();
		for (ClanChannelMember m : channel.getMembers())
		{
			names.add(Text.standardize(m.getName()));
		}
		return names;
	}

	private Filter buildFilter()
	{
		return Filter.of(config.includeSelf(), config.onlyMyTarget(), config.minimumCount(), config.npcNames());
	}

	@Provides
	NpcAttackerCountConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NpcAttackerCountConfig.class);
	}
}

