package com.npcattackercount;

import net.runelite.api.coords.Angle;

/**
 * Which neighbouring tile a player is facing.
 *
 * The game never says which object a player is using - only actors can be
 * "interacted with" in client state. But a skilling player turns to face the
 * object and plays an animation, so "animating and facing a tile" is the
 * observable stand-in for "using what's on that tile".
 */
final class Facing
{
	private Facing()
	{
	}

	/** Scene-tile step {dx, dy} for an orientation (0 = south, 512 = west, 1024 = north, 1536 = east). */
	static int[] step(int orientation)
	{
		switch (new Angle(orientation).getNearestDirection())
		{
			case NORTH:
				return new int[]{0, 1};
			case EAST:
				return new int[]{1, 0};
			case WEST:
				return new int[]{-1, 0};
			case SOUTH:
			default:
				return new int[]{0, -1};
		}
	}
}
